import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    ys = [0] * (n + 2)
    for x, y in zip(data[1::2], data[2::2]):
        ys[x] = y
    ys[0] = n + 1

    pref = [[0] * (n + 1) for _ in range(n + 1)]
    for x in range(1, n + 1):
        row = pref[x]
        previous = pref[x - 1]
        value = ys[x]
        seen = 0
        for y in range(1, n + 1):
            if y == value:
                seen = 1
            row[y] = previous[y] + seen

    def no_isolated(left, top, right, bottom):
        if right - left <= 1 or top - bottom <= 1:
            return True
        pr = pref
        for x in range(left + 1, right):
            y = ys[x]
            if bottom < y < top:
                southwest = (pr[x - 1][y - 1] - pr[left][y - 1]
                             - pr[x - 1][bottom] + pr[left][bottom])
                if southwest == 0:
                    northeast = (pr[right - 1][top - 1] - pr[x][top - 1]
                                 - pr[right - 1][y] + pr[x][y])
                    if northeast == 0:
                        return False
        return True

    dp = [0] * (n + 1)
    for left in range(n, -1, -1):
        top = ys[left]
        result = int(no_isolated(left, top, n + 1, 0))
        for right in range(left + 1, n + 1):
            bottom = ys[right]
            if bottom < top and no_isolated(left, top, right, bottom):
                result += dp[right]
        dp[left] = result % MOD
    print(dp[0])

if __name__ == '__main__':
    main()

