import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    limit = n + 1

    # ban[l][x] is the smallest right endpoint of a condition
    # with X=x and L>=l. If ban[l][x]<=r, x cannot be the
    # maximum position of the interval [l,r].
    ban = [[limit] * (n + 2) for _ in range(n + 2)]
    for i in range(2, len(data), 3):
        l, r, x = data[i:i + 3]
        if r < ban[l][x]:
            ban[l][x] = r
    for l in range(n - 1, 0, -1):
        row, next_row = ban[l], ban[l + 1]
        for x in range(l, n + 1):
            if next_row[x] < row[x]:
                row[x] = next_row[x]

    inv = [0] * (n + 1)
    inv[1] = 1
    for i in range(2, n + 1):
        inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD

    # dp[l][r] is the valid count divided by (r-l+1)!.
    dp = [[0] * (n + 2) for _ in range(n + 2)]
    for l in range(1, n + 2):
        dp[l][l - 1] = 1
    for length in range(1, n + 1):
        inverse_length = inv[length]
        for l in range(1, n - length + 2):
            r = l + length - 1
            row, forbidden = dp[l], ban[l]
            total = 0
            for k in range(l, r + 1):
                if forbidden[k] > r:
                    total += row[k - 1] * dp[k + 1][r]
            row[r] = total % MOD * inverse_length % MOD

    factorial = 1
    for i in range(2, n + 1):
        factorial = factorial * i % MOD
    print(dp[1][n] * factorial % MOD)

if __name__ == '__main__':
    main()

