import sys
from array import array
from collections import deque

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    a = [v - 1 for v in data[2:]]

    deg = [0] * n
    for v in a:
        deg[v] += 1

    q = deque(i for i in range(n) if deg[i] == 0)
    dp = [None] * n

    while q:
        v = q.popleft()
        p = a[v]
        child = dp[v]
        parent = dp[p]
        if parent is None:
            parent = array('I', [1]) * m
            dp[p] = parent

        if child is None:
            for j in range(m):
                parent[j] = parent[j] * (j + 1) % MOD
        else:
            prefix = 0
            for j in range(m):
                prefix += child[j]
                if prefix >= MOD:
                    prefix -= MOD
                parent[j] = parent[j] * prefix % MOD

        dp[v] = None
        deg[p] -= 1
        if deg[p] == 0:
            q.append(p)

    answer = 1
    for i in range(n):
        if deg[i] == 0:
            continue
        cycle = []
        v = i
        while deg[v]:
            deg[v] = 0
            cycle.append(v)
            v = a[v]

        if len(cycle) == 1:
            values = dp[cycle[0]]
            total = m if values is None else sum(values) % MOD
        else:
            values = dp[cycle[0]]
            merged = array('I', [1]) * m if values is None else values
            for v in cycle[1:]:
                values = dp[v]
                if values is not None:
                    for j in range(m):
                        merged[j] = merged[j] * values[j] % MOD
            total = sum(merged) % MOD
        answer = answer * total % MOD

    print(answer)


if __name__ == '__main__':
    main()

