def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    a = data[1:]
    limit = max(a)

    phi = list(range(limit + 1))
    for p in range(2, limit + 1):
        if phi[p] == p:
            for v in range(p, limit + 1, p):
                phi[v] -= phi[v] // p

    divisors = [[] for _ in range(limit + 1)]
    for d in range(1, limit + 1):
        for v in range(d, limit + 1, d):
            divisors[v].append(d)

    mod = 998244353
    sums = [0] * (limit + 1)
    power = 1
    answer = 0
    output = []
    for x in a:
        added = 0
        for d in divisors[x]:
            added += phi[d] * sums[d]
            updated = sums[d] + power
            if updated >= mod:
                updated -= mod
            sums[d] = updated
        answer = (answer * 2 + added) % mod
        output.append(str(answer))
        power = power * 2 % mod

    sys.stdout.write('\n'.join(output))

