import sys
from array import array

def main():
    inp = sys.stdin.buffer
    n, q = map(int, inp.readline().split())
    parent = array('i', range(n + 1))
    left = array('i', range(n + 1))
    right = array('i', range(n + 1))
    color = array('i', range(n + 1))
    size = array('i', [1]) * (n + 1)
    count = array('i', [1]) * (n + 1)

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def merge(a, b):
        if size[a] < size[b]:
            a, b = b, a
        parent[b] = a
        size[a] += size[b]
        if left[b] < left[a]:
            left[a] = left[b]
        if right[b] > right[a]:
            right[a] = right[b]
        return a

    out = []
    for _ in range(q):
        row = list(map(int, inp.readline().split()))
        if row[0] == 2:
            out.append(str(count[row[1]]))
        else:
            _, x, c = row
            r = find(x)
            old = color[r]
            if old == c:
                continue
            count[old] -= size[r]
            count[c] += size[r]
            color[r] = c
            if left[r] > 1:
                a = find(left[r] - 1)
                if color[a] == c:
                    r = merge(r, a)
            if right[r] < n:
                a = find(right[r] + 1)
                if color[a] == c:
                    r = merge(r, a)
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

