        typ = next(it)
        if typ == 1:
            idx = next(it)-1
            closed.add(idx)
            queries.append((1, idx, 0))
        else:
            queries.append((2, next(it)-1, next(it)-1))

    inf = 10**20
    d = [[inf]*n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0
    for idx, (a, b, w) in enumerate(edges):
        if idx not in closed:
            d[a][b] = w
            d[b][a] = w

    for k in range(n):
        dk = d[k]
        for i in range(n):
            di = d[i]
            v = di[k]
            if v == inf:
                continue
            for j in range(n):
                candidate = v + dk[j]
                if candidate < di[j]:
                    di[j] = candidate

    answers = []
    for typ, x, y in reversed(queries):
        if typ == 2:
            v = d[x][y]
