class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        mod = 1000000007
        length = len(s)
        fact = [1] * (length + 1)
        for i in range(1, length + 1):
            fact[i] = fact[i - 1] * i % mod
        invfact = [1] * (length + 1)
        invfact[length] = pow(fact[length], mod - 2, mod)
        for i in range(length, 0, -1):
            invfact[i - 1] = invfact[i] * i % mod

        counts = [0] * (length + 1)
        prefix = 0
        for index, bit in enumerate(s):
            if bit == '1':
                remaining = length - index - 1
                base = fact[remaining]
                for additional in range(remaining + 1):
                    counts[prefix + additional] += (base * invfact[additional] % mod) * invfact[remaining - additional] % mod
                prefix += 1

        steps = [0] * (length + 1)
        for i in range(2, length + 1):
            steps[i] = steps[i.bit_count()] + 1
        return sum(counts[i] for i in range(1, length + 1) if steps[i] + 1 <= k) % mod

