import heapq

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    h, w, x, p, q = data[:5]
    a = data[5:]
    start = (p-1)*w+q-1
    strength = a[start]
    seen = bytearray(h*w)
    seen[start] = 1
    heap = []
    def add(v):
        if not seen[v]:
            seen[v] = 1
            heapq.heappush(heap, (a[v], v))
    def neighbors(v):
        if v >= w: add(v-w)
        if v < (h-1)*w: add(v+w)
        if v % w: add(v-1)
        if v % w != w-1: add(v+1)
    neighbors(start)
    while heap and heap[0][0]*x < strength:
        val, v = heapq.heappop(heap)
        strength += val
        neighbors(v)
    print(strength)

