    for i in range(2, len(a), 2):
        u, v = a[i] - 1, a[i + 1] - 1
        rows[u] ^= 1 << v
        rows[v] ^= 1 << u

    pivot = {}
    for row in rows:
        while row:
            p = (row & -row).bit_length() - 1
            if p in pivot:
                row ^= pivot[p]
            else:
                pivot[p] = row
                break

