from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        a = [v for row in grid for v in row]
        directions = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        answer = 0
        for k, (dr, dc) in enumerate(directions):
            tr, tc = directions[(k + 1) % 4]
            suffix = [0] * (n * m)
            rows = range(n - 1, -1, -1) if tr == 1 else range(n)
            cols = range(m - 1, -1, -1) if tc == 1 else range(m)
            for r in rows:
                for c in cols:
                    pos = r * m + c
                    value = a[pos]
                    if value == 1:
                        continue
                    nr, nc = r + tr, c + tc
                    length = 1
                    if 0 <= nr < n and 0 <= nc < m and a[nr * m + nc] == 2 - value:
                        length += suffix[nr * m + nc]
                    suffix[pos] = length
            prefix = [0] * (n * m)
            rows = range(n) if dr == 1 else range(n - 1, -1, -1)
            cols = range(m) if dc == 1 else range(m - 1, -1, -1)
            for r in rows:
                for c in cols:
                    pos = r * m + c
                    value = a[pos]
                    if value == 1:
                        length = 1
                    else:
                        pr, pc = r - dr, c - dc
                        length = 0
                        if 0 <= pr < n and 0 <= pc < m:
                            previous = a[pr * m + pc]
                            if (value == 2 and previous in (1, 0) or value == 0 and previous == 2):
                                old = prefix[pr * m + pc]
                                if old:
                                    length = old + 1
                    prefix[pos] = length
                    if length:
                        nr, nc = r + tr, c + tc
                        total = length
                        if 0 <= nr < n and 0 <= nc < m and a[nr * m + nc] == (2 if value != 2 else 0):
                            total += suffix[nr * m + nc]
                        if total > answer:
                            answer = total
