class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        weights = [0] * m
        for i in range(m):
            j = n - 1 - i
            weights[i] = powers[i] if i == j else (powers[i] + powers[j]) % k

        mask = (1 << k) - 1
        reachable = [0] * (m + 1)
        reachable[m] = 1
        for i in range(m - 1, -1, -1):
            previous = reachable[i + 1]
            bits = 0
            for digit in range(10):
                shift = digit * weights[i] % k
                bits |= ((previous << shift) | (previous >> (k - shift))) & mask
            reachable[i] = bits

        first_half = []
        remainder = 0
        for i in range(m):
            for digit in range(9, 0 if i == 0 else -1, -1):
                new_remainder = (remainder + digit * weights[i]) % k
                if reachable[i + 1] & (1 << (-new_remainder % k)):
                    first_half.append(str(digit))
                    remainder = new_remainder
                    break

        left = ''.join(first_half)
        return left + (left[::-1] if n % 2 == 0 else left[-2::-1])

