from functools import cmp_to_key


def compare(x, y):
    a, b = x
    c, d = y
    diff = b * (c - 1) - d * (a - 1)
    if diff > 0:
        return -1
    if diff < 0:
        return 1
    return 0


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, k = data[:2]
    counts = {}
    for i in range(2, 2 * n + 2, 2):
        key = (data[i], data[i + 1])
        counts[key] = counts.get(key, 0) + 1

    dp = [-1] * (k + 1)
    dp[0] = 1
    for a, b in sorted(counts, key=cmp_to_key(compare)):
        for _ in range(min(k, counts[a, b])):
            for j in range(k, 0, -1):
                if dp[j - 1] >= 0:
                    candidate = a * dp[j - 1] + b
                    if candidate > dp[j]:
                        dp[j] = candidate
    print(dp[k])


