from typing import List

class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        adj = [[] for _ in range(n)]
        total = 0
        for u, v, w in edges:
            adj[u].append((v, w))
            adj[v].append((u, w))
            total += w
        if all(len(a) <= k for a in adj):
            return total

        parent = [-1] * n
        parent[0] = 0
        order = [0]
        for u in order:
            for v, w in adj[u]:
                if v != parent[u]:
                    parent[v] = u
                    order.append(v)

        dp0 = [0] * n
        dp1 = [0] * n
        for u in reversed(order):
            base = 0
            gains = []
            for v, w in adj[u]:
                if v == parent[u]:
                    continue
                base += dp0[v]
                gain = w + dp1[v] - dp0[v]
                if gain > 0:
                    gains.append(gain)
            gains.sort(reverse=True)
            dp1[u] = base + sum(gains[:k-1])
            dp0[u] = dp1[u] + (gains[k-1] if len(gains) >= k else 0)
        return dp0[0]

