class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(t):
            if not t:
                return range(n + 1)
            m = len(t)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = pi[j - 1]
            return result

        def next_positions(t):
            if not t:
                return list(range(n + 1)) + [n + 1]
            marked = bytearray(n + 1)
            for i in occurrences(t):
                marked[i] = 1
            nxt = [n + 1] * (n + 2)
            nearest = n + 1
            for i in range(n, -1, -1):
                if marked[i]:
                    nearest = i
                nxt[i] = nearest
            return nxt

        nb = next_positions(b)
        nc = next_positions(c)
        answer = n + 1
        for start in occurrences(a):
            middle = nb[start + len(a)]
            if middle == n + 1:
                continue
            end_start = nc[middle + len(b)]
            if end_start != n + 1:
                answer = min(answer, end_start + len(c) - start)
        return answer if answer <= n else -1

