        x, y, z = data[i:i + 3]
        x -= 1
        y -= 1
        graph[x].append((y, z))
        graph[y].append((x, z))

    potential = [-1] * n
    answer = [0] * n
    for start in range(n):
        if potential[start] != -1:
            continue
        potential[start] = 0
        nodes = [start]
        counts = [0] * 30
        pos = 0
        while pos < len(nodes):
            u = nodes[pos]
            pos += 1
            p = potential[u]
            bit = 0
            while p:
                if p & 1:
                    counts[bit] += 1
                p >>= 1
                bit += 1
            for v, z in graph[u]:
                q = potential[u] ^ z
                if potential[v] == -1:
                    potential[v] = q
                    nodes.append(v)
                elif potential[v] != q:
                    print(-1)
                    return

        mask = 0
        size = len(nodes)
        for bit, count in enumerate(counts):
            if count * 2 > size:
                mask |= 1 << bit
        for u in nodes:
            answer[u] = potential[u] ^ mask

    sys.stdout.write(' '.join(map(str, answer)) + '\n')

