import sys

def solve(a,b):
    x=[i for i,v in enumerate(a) if v==49]
    y=[i for i,v in enumerate(b) if v==49]
    p=[x[i+1]-x[i] for i in range(len(x)-1)]
    q=[y[i+1]-y[i] for i in range(len(y)-1)]
    if len(q)>len(p):
        return -1
    bounds=[0]*len(q)
    j=len(p)-1
    for k in range(len(q)-1,-1,-1):
        while j>=0 and p[j]<q[k]:
            j-=1
        if j<0:
            return -1
        bounds[k]=j
        j-=1
    pos=0
    odd=0
    for k,e in enumerate(q):
        bound=bounds[k]
        first=-1
        firstodd=-1
        z=pos
        while z<=bound:
            d=p[z]
            if d>=e and first<0:
                first=z
            if d&1:
                if d>=e:
                    firstodd=z
                break
            z+=1
        if first<0:
            if firstodd>=0:
                first=firstodd
            else:
                z+=1
                while z<=bound and p[z]<e:
                    z+=1
                if z>bound:
                    return -1
                first=z
        if e&1 and firstodd>=0:
            first=firstodd
        while pos<first:
            odd+=p[pos]&1
            pos+=1
        odd+=(p[pos]-e)&1
        pos+=1
    while pos<len(p):
        odd+=p[pos]&1
        pos+=1
    D=x[-1]-x[0]-y[-1]+y[0]
    return max((D+odd)//2,y[0]-x[0],x[-1]-y[-1])

