import sys
from collections import deque

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, W = data[0], data[1]
    neg = -10**30
    dp = [neg] * (W + 1)
    dp[0] = 0
    for i in range(n):
        w, v = data[2 + 2*i], data[3 + 2*i]
        if v == 1:
            continue
        for r in range(w):
            hull = deque()
            j = 0
            for pos in range(r, W+1, w):
                old = dp[pos]
                if old != neg:
                    b = old - j*v - j*j
                    while len(hull) >= 2:
                        t1, b1 = hull[-2]
                        t2, b2 = hull[-1]
                        if (b1-b2)*(j-t2) >= (b2-b)*(t2-t1):
                            hull.pop()
                        else:
                            break
                    hull.append((j, b))
                while len(hull) >= 2:
                    t1, b1 = hull[0]
                    t2, b2 = hull[1]
                    if 2*j*(t2-t1) >= b1-b2:
                        hull.popleft()
                    else:
                        break
                if hull:
                    t, b = hull[0]
                    dp[pos] = j*v - j*j + 2*j*t + b
                j += 1
    print(max(dp))

if __name__ == '__main__':
    main()

