from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        starts = [0] * n
        ends = [0] * n
        order = []
        stack = [(0, 0)]
        while stack:
            x, phase = stack.pop()
            if phase:
                order.append(s[x])
                ends[x] = len(order)
            else:
                starts[x] = len(order)
                stack.append((x, 1))
                for y in reversed(children[x]):
                    stack.append((y, 0))

        d1 = [0] * n
        l, r = 0, -1
        for i in range(n):
            k = 1 if i > r else min(d1[l + r - i], r - i + 1)
            while i - k >= 0 and i + k < n and order[i - k] == order[i + k]:
                k += 1
            d1[i] = k
            if i + k - 1 > r:
                l, r = i - k + 1, i + k - 1

        d2 = [0] * n
        l, r = 0, -1
        for i in range(n):
            k = 0 if i > r else min(d2[l + r - i + 1], r - i + 1)
            while i - k - 1 >= 0 and i + k < n and order[i - k - 1] == order[i + k]:
                k += 1
            d2[i] = k
            if i + k - 1 > r:
                l, r = i - k, i + k - 1

        ans = [False] * n
        for i in range(n):
            a, b = starts[i], ends[i]
            length = b - a
            if length & 1:
                ans[i] = d1[(a + b - 1) // 2] >= (length + 1) // 2
            else:
                ans[i] = d2[(a + b) // 2] >= length // 2
        return ans

