from typing import List
from math import gcd

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        n = len(nums)
        prefix_gcd = [0] * (n + 1)
        prefix_lcm = [1] * (n + 1)
        suffix_gcd = [0] * (n + 1)
        suffix_lcm = [1] * (n + 1)

        def lcm(a, b):
            return a // gcd(a, b) * b

        for i, x in enumerate(nums):
            prefix_gcd[i + 1] = gcd(prefix_gcd[i], x)
            prefix_lcm[i + 1] = lcm(prefix_lcm[i], x)
        for i in range(n - 1, -1, -1):
            suffix_gcd[i] = gcd(suffix_gcd[i + 1], nums[i])
            suffix_lcm[i] = lcm(suffix_lcm[i + 1], nums[i])

        answer = prefix_gcd[n] * prefix_lcm[n]
        if n > 1:
            for i in range(n):
                score = gcd(prefix_gcd[i], suffix_gcd[i + 1]) * lcm(prefix_lcm[i], suffix_lcm[i + 1])
                answer = max(answer, score)
        return answer

