class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        mod = 1000000007
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - 97] += 1
        for _ in range(t):
            counts = [counts[25], (counts[0] + counts[25]) % mod] + counts[1:25]
        return sum(counts) % mod

