import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        limit = 10 ** len(str(n))
        low = limit // 10
        prime = bytearray(b'\x01') * limit
        prime[0:2] = b'\x00\x00'
        for i in range(2, int(limit ** .5) + 1):
            if prime[i]:
                prime[i*i:limit:i] = b'\x00' * (((limit - 1 - i*i) // i) + 1)
        if prime[n] or prime[m]:
            return -1
        dist = [float('inf')] * limit
        dist[n] = n
        heap = [(n, n)]
        while heap:
            cost, x = heapq.heappop(heap)
            if cost != dist[x]:
                continue
            if x == m:
                return cost
            p = 1
            while p < limit:
                d = x // p % 10
                if d < 9:
                    y = x + p
                    if y < limit and not prime[y] and cost + y < dist[y]:
                        dist[y] = cost + y
                        heapq.heappush(heap, (dist[y], y))
                if d > 0:
                    y = x - p
                    if y >= low and not prime[y] and cost + y < dist[y]:
                        dist[y] = cost + y
                        heapq.heappush(heap, (dist[y], y))
                p *= 10
        return -1

