from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        # dp[j] stores the longest common prefix of nums[i:] and nums[j:].
        dp = [0] * (n + 1)
        answer = 0
        for i in range(n - 2, 0, -1):
            first_is_prefix = z[i] >= i
            for j in range(i + 1, n):
                if nums[i] == nums[j]:
                    dp[j] = dp[j + 1] + 1
                else:
                    dp[j] = 0
                if (first_is_prefix and j >= 2 * i) or (j - i <= n - j and dp[j] >= j - i):
                    answer += 1
        return answer

