def main():
    data = sys.stdin.buffer.read().split()
    s, t = data[1], data[2]
    a, b = len(s), len(t)
    if abs(a-b) > 1:
        print('No')
    elif a == b:
        mismatches = 0
        for x, y in zip(s, t):
            if x != y:
                mismatches += 1
                if mismatches > 1:
                    print('No')
                    return
        print('Yes')
    else:
        if a < b:
            s, t = t, s
        i = 0
        while i < len(t) and s[i] == t[i]:
            i += 1
        print('Yes' if s[i+1:] == t[i:] else 'No')

if __name__ == '__main__':
    main()

