class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        pairs = [(a, b) for a in range(3) for b in range(3) if a != b]
        transitions = [[j for j, (c, d) in enumerate(pairs) if a != c and b != d]
                       for a, b in pairs]
        dp = [cost[0][a] + cost[n - 1][b] for a, b in pairs]
        for i in range(1, n // 2):
            left, right = cost[i], cost[n - 1 - i]
            ndp = [10**20] * 6
            for j, (a, b) in enumerate(pairs):
                val = dp[j]
                for k in transitions[j]:
                    c, d = pairs[k]
                    v = val + left[c] + right[d]
                    if v < ndp[k]:
                        ndp[k] = v
            dp = ndp
        return min(dp)

