class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        t = '1' + s + '1'
        runs = []
        for c in t:
            if runs and runs[-1][0] == c:
                runs[-1][1] += 1
            else:
                runs.append([c, 1])

        m = len(runs)
        pref = [0] * (m + 1)
        for i in range(m):
            pref[i + 1] = max(pref[i], runs[i][1] if runs[i][0] == '0' else 0)
        suff = [0] * (m + 1)
        for i in range(m - 1, -1, -1):
            suff[i] = max(suff[i + 1], runs[i][1] if runs[i][0] == '0' else 0)

        original = s.count('1')
        ans = original
        for i in range(1, m - 1):
            if runs[i][0] == '1' and runs[i-1][0] == '0' and runs[i+1][0] == '0':
                merged = runs[i-1][1] + runs[i][1] + runs[i+1][1]
                best_zero = max(merged, pref[i-1], suff[i+2])
                ans = max(ans, original - runs[i][1] + best_zero)
        return ans

