class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = {'a': 1, 'e': 2, 'i': 4, 'o': 8, 'u': 16}
        ans = 0
        n = len(word)
        for i in range(n):
            mask = 0
            consonants = 0
            for j in range(i, n):
                bit = vowels.get(word[j], 0)
                if bit:
                    mask |= bit
                else:
                    consonants += 1
                    if consonants > k:
                        break
                if consonants == k and mask == 31:
                    ans += 1
        return ans

